PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('curated','mediawiki-xml','canonical-html')),game_version TEXT NOT NULL,url TEXT,retrieved_at TEXT NOT NULL,license TEXT NOT NULL,content_hash TEXT,UNIQUE(name,game_version,url));
CREATE TABLE IF NOT EXISTS entities(id TEXT PRIMARY KEY,slug TEXT NOT NULL,kind TEXT NOT NULL,name TEXT NOT NULL,description TEXT,tags_json TEXT NOT NULL,source_json TEXT NOT NULL,metadata_json TEXT,game_version TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(slug,kind,game_version));
CREATE TABLE IF NOT EXISTS claims(id TEXT PRIMARY KEY,entity_id TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,source_id TEXT NOT NULL REFERENCES sources(id),field TEXT NOT NULL,value_json TEXT NOT NULL,evidence TEXT NOT NULL,locator TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(entity_id,source_id,field,value_json));
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,title TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversation_messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN('user','assistant','system','tool')),content TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(conversation_id,ordinal));
CREATE VIRTUAL TABLE IF NOT EXISTS entity_fts USING fts5(id UNINDEXED,name,description,tags,content='entities',content_rowid='rowid',tokenize='unicode61');
CREATE TRIGGER IF NOT EXISTS entity_fts_ai AFTER INSERT ON entities BEGIN INSERT INTO entity_fts(rowid,id,name,description,tags) VALUES(new.rowid,new.id,new.name,coalesce(new.description,''),new.tags_json); END;
CREATE TRIGGER IF NOT EXISTS entity_fts_ad AFTER DELETE ON entities BEGIN INSERT INTO entity_fts(entity_fts,rowid,id,name,description,tags) VALUES('delete',old.rowid,old.id,old.name,coalesce(old.description,''),old.tags_json); END;
CREATE TRIGGER IF NOT EXISTS entity_fts_au AFTER UPDATE ON entities BEGIN INSERT INTO entity_fts(entity_fts,rowid,id,name,description,tags) VALUES('delete',old.rowid,old.id,old.name,coalesce(old.description,''),old.tags_json); INSERT INTO entity_fts(rowid,id,name,description,tags) VALUES(new.rowid,new.id,new.name,coalesce(new.description,''),new.tags_json); END;
